package tr.kasadenge.app;
import android.content.*;import android.database.*;import android.database.sqlite.*;import org.json.*;import java.time.*;import java.util.*;
final class CashDb extends SQLiteOpenHelper {
 CashDb(Context c){super(c,"kasadenge_v1.db",null,3);}
 @Override public void onCreate(SQLiteDatabase d){PosLedger.create(d);d.execSQL("CREATE TABLE pos_revisions (id INTEGER PRIMARY KEY AUTOINCREMENT, data TEXT NOT NULL)");d.execSQL("CREATE TABLE pos (id TEXT PRIMARY KEY, data TEXT NOT NULL)");d.execSQL("CREATE TABLE settings (id INTEGER PRIMARY KEY CHECK(id=1), data TEXT NOT NULL)");d.execSQL("CREATE TABLE entries (id TEXT PRIMARY KEY, cash_id TEXT NOT NULL, day TEXT NOT NULL, data TEXT NOT NULL, UNIQUE(cash_id,day))");d.execSQL("CREATE TABLE revisions (id INTEGER PRIMARY KEY AUTOINCREMENT, entry_id TEXT NOT NULL, data TEXT NOT NULL)");d.execSQL("CREATE TABLE drafts (id TEXT PRIMARY KEY, data TEXT NOT NULL)");try{ContentValues v=new ContentValues();v.put("id",1);v.put("data",defaults().toString());d.insertOrThrow("settings",null,v);}catch(Exception e){throw new IllegalStateException(e);}}
 @Override public void onUpgrade(SQLiteDatabase d,int old,int version){if(old<2){d.execSQL("CREATE TABLE IF NOT EXISTS pos (id TEXT PRIMARY KEY, data TEXT NOT NULL)");d.execSQL("CREATE TABLE IF NOT EXISTS pos_revisions (id INTEGER PRIMARY KEY AUTOINCREMENT, data TEXT NOT NULL)");}if(old<3)PosLedger.create(d);}
 static JSONObject defaults()throws Exception{JSONArray ds=new JSONArray();for(int v:new int[]{200,100,50,20,10,5})ds.put(new JSONObject().put("id","p"+v).put("label",v+" TL").put("kind","paper").put("value",v*100).put("active",true));ds.put(new JSONObject().put("id","c5").put("label","5 TL (Madeni)").put("kind","coin").put("value",500).put("active",true));return new JSONObject().put("theme","system").put("cashboxes",new JSONArray()).put("denoms",ds);}
 static long number(JSONObject o,String k)throws Exception{Object v=o.get(k);String s=String.valueOf(v);if(!s.matches("[0-9]{1,13}"))throw new Exception("Geçersiz sayısal alan: "+k);return CashMath.checked(Long.parseLong(s));}
 static String text(JSONObject o,String k,int max)throws Exception{String t=o.getString(k).trim();if(t.isEmpty()||t.length()>max)throw new Exception("Alan boş veya çok uzun: "+k);return t;}
 static String day(JSONObject o)throws Exception{String s=o.getString("date");if(!s.matches("[0-9]{4}-[0-9]{2}-[0-9]{2}"))throw new Exception("Tarih geçersiz.");LocalDate x=LocalDate.parse(s);if(x.isAfter(LocalDate.now()))throw new Exception("Gelecek tarihli kapanış kaydedilemez.");return s;}
 static JSONObject config(JSONObject in)throws Exception{JSONObject c=new JSONObject();String theme=in.optString("theme","system");if(!Arrays.asList("system","light","dark").contains(theme))throw new Exception("Tema geçersiz.");c.put("theme",theme);JSONArray boxes=in.getJSONArray("cashboxes"),ds=in.getJSONArray("denoms");if(boxes.length()>100||ds.length()<1||ds.length()>40)throw new Exception("Kasa veya para türü sayısı geçersiz.");Set<String> ids=new HashSet<>();JSONArray clean=new JSONArray();boolean active=false;for(int i=0;i<boxes.length();i++){JSONObject b=boxes.getJSONObject(i);String id=text(b,"id",80);if(!id.matches("[a-zA-Z0-9_-]+")||!ids.add(id))throw new Exception("Kasa kimliği tekrarlı veya geçersiz.");String posMode=b.optString("posMode","detailed");if(!Arrays.asList("detailed","total").contains(posMode))throw new Exception("POS Giriş Türü Geçersiz.");boolean on=b.optBoolean("active",true);active|=on;clean.put(new JSONObject().put("id",id).put("name",text(b,"name",60)).put("advance",number(b,"advance")).put("posMode",posMode).put("active",on));}c.put("cashboxes",clean);clean=new JSONArray();ids.clear();active=false;for(int i=0;i<ds.length();i++){JSONObject d=ds.getJSONObject(i);String id=text(d,"id",80),kind=d.getString("kind");long value=number(d,"value");if(!id.matches("[a-zA-Z0-9_-]+")||!ids.add(id)||!Arrays.asList("paper","coin").contains(kind)||value<1)throw new Exception("Para türü geçersiz.");boolean on=d.optBoolean("active",true);active|=on;clean.put(new JSONObject().put("id",id).put("label",text(d,"label",50)).put("kind",kind).put("value",value).put("active",on));}if(!active)throw new Exception("En az bir etkin para türü gerekli.");return c.put("denoms",clean);}
 synchronized JSONObject settings()throws Exception{try(Cursor c=getReadableDatabase().rawQuery("SELECT data FROM settings WHERE id=1",null)){if(!c.moveToFirst())throw new Exception("Ayarlar okunamadı; veriler korunuyor.");return new JSONObject(c.getString(0));}}
 synchronized JSONArray rows(String table)throws Exception{JSONArray a=new JSONArray();try(Cursor c=getReadableDatabase().rawQuery("SELECT data FROM "+table+(table.equals("entries")?" ORDER BY day DESC":table.equals("revisions")?" ORDER BY id":""),null)){while(c.moveToNext())a.put(new JSONObject(c.getString(0)));}return a;}
 synchronized JSONObject state()throws Exception{return new JSONObject().put("schema",3).put("posTotals",rows("pos_totals")).put("settlements",rows("pos_settlements")).put("ledgerRevisions",rows("pos_ledger_revisions")).put("pos",rows("pos")).put("posRevisions",rows("pos_revisions")).put("app","kasadenge").put("settings",settings()).put("entries",rows("entries")).put("drafts",rows("drafts")).put("revisions",rows("revisions"));}
 synchronized void saveConfig(String raw)throws Exception{JSONObject c=config(new JSONObject(raw)),old=settings();Set<String> b=new HashSet<>(),d=new HashSet<>();for(int i=0;i<c.getJSONArray("cashboxes").length();i++)b.add(c.getJSONArray("cashboxes").getJSONObject(i).getString("id"));for(int i=0;i<c.getJSONArray("denoms").length();i++)d.add(c.getJSONArray("denoms").getJSONObject(i).getString("id"));for(int i=0;i<old.getJSONArray("cashboxes").length();i++){JSONObject x=old.getJSONArray("cashboxes").getJSONObject(i);if(!b.contains(x.getString("id")))c.getJSONArray("cashboxes").put(x.put("active",false));}for(int i=0;i<old.getJSONArray("denoms").length();i++){JSONObject x=old.getJSONArray("denoms").getJSONObject(i);if(!d.contains(x.getString("id")))c.getJSONArray("denoms").put(x.put("active",false));}ContentValues v=new ContentValues();v.put("data",c.toString());getWritableDatabase().update("settings",v,"id=1",null);}
 static JSONObject validate(JSONObject in)throws Exception{String cash=text(in,"cashId",80);if(!cash.matches("[a-zA-Z0-9_-]+"))throw new Exception("Kasa kimliği geçersiz.");JSONObject r=new JSONObject().put("cashId",cash).put("cashName",text(in,"cashName",60)).put("date",day(in));long expected=number(in,"expected"),advance=number(in,"advance"),other=number(in,"other"),paper=0,coins=0;JSONArray lines=in.getJSONArray("lines"),out=new JSONArray();Set<String> ids=new HashSet<>();if(lines.length()<1||lines.length()>40)throw new Exception("Para satırları geçersiz.");for(int i=0;i<lines.length();i++){JSONObject l=lines.getJSONObject(i);String id=text(l,"id",80),kind=l.getString("kind");if(!ids.add(id)||!Arrays.asList("paper","coin").contains(kind))throw new Exception("Tekrarlı veya geçersiz para satırı.");long value=number(l,"value"),count=number(l,"count"),sum=CashMath.line(value,count);if(kind.equals("paper"))paper=CashMath.add(paper,sum);else coins=CashMath.add(coins,sum);out.put(new JSONObject().put("id",id).put("label",text(l,"label",50)).put("kind",kind).put("value",value).put("count",count));}long[] totals=CashMath.totals(expected,advance,paper,coins,other);String note=in.optString("note","").trim();if(note.length()>1000)throw new Exception("Not en fazla 1000 karakter olabilir.");return r.put("id",cash+"_"+r.getString("date")).put("expected",expected).put("advance",advance).put("other",other).put("lines",out).put("note",note).put("paper",paper).put("coins",coins).put("target",totals[0]).put("counted",totals[1]).put("remaining",totals[2]).put("diff",totals[3]).put("net",totals[4]);}
 JSONObject find(String id)throws Exception{try(Cursor c=getReadableDatabase().rawQuery("SELECT data FROM entries WHERE id=?",new String[]{id})){return c.moveToFirst()?new JSONObject(c.getString(0)):null;}}
 synchronized JSONObject closeCount(String raw)throws Exception{JSONObject in=new JSONObject(raw),r=validate(in),cfg=settings();boolean found=false,active=false;for(int i=0;i<cfg.getJSONArray("cashboxes").length();i++)if(cfg.getJSONArray("cashboxes").getJSONObject(i).getString("id").equals(r.getString("cashId"))){found=true;active=cfg.getJSONArray("cashboxes").getJSONObject(i).optBoolean("active");}if(!found)throw new Exception("Kasa bulunamadı.");JSONObject old=find(r.getString("id"));if(old==null&&!active)throw new Exception("Arşivdeki kasayı yeni kapanış için önce etkinleştirin.");String reason=in.optString("reason","").trim();if(old!=null&&reason.length()<3)throw new Exception("Kapanış zaten var. Düzeltme gerekçesini yazın.");if(old!=null&&in.optInt("baseRevision")!=old.getInt("revision"))throw new Exception("Kayıt değişti. Güncel kaydı tekrar açın.");r.put("revision",old==null?1:old.getInt("revision")+1).put("savedAt",System.currentTimeMillis()).put("reason",reason);SQLiteDatabase d=getWritableDatabase();d.beginTransaction();try{if(old!=null){ContentValues v=new ContentValues();v.put("entry_id",r.getString("id"));v.put("data",old.toString());d.insertOrThrow("revisions",null,v);}putEntry(d,r);d.delete("drafts","id=?",new String[]{r.getString("id")});d.setTransactionSuccessful();}finally{d.endTransaction();}return r;}
 static void putEntry(SQLiteDatabase d,JSONObject r)throws Exception{ContentValues v=new ContentValues();v.put("id",r.getString("id"));v.put("cash_id",r.getString("cashId"));v.put("day",r.getString("date"));v.put("data",r.toString());d.insertWithOnConflict("entries",null,v,SQLiteDatabase.CONFLICT_REPLACE);}
 synchronized void draft(String raw)throws Exception{JSONObject x=new JSONObject(raw);String cash=text(x,"cashId",80),date=x.getString("date");LocalDate.parse(date);if(raw.length()>60000)throw new Exception("Taslak çok büyük.");ContentValues v=new ContentValues();v.put("id",cash+"_"+date);v.put("data",x.toString());getWritableDatabase().insertWithOnConflict("drafts",null,v,SQLiteDatabase.CONFLICT_REPLACE);}
 synchronized String merge(String raw)throws Exception{JSONObject in=new JSONObject(raw);if(!"kasadenge".equals(in.optString("app"))||(in.optInt("schema")!=1&&in.optInt("schema")!=2&&in.optInt("schema")!=3))throw new Exception("KasaDenge yedeği gerekli.");JSONObject incoming=config(in.getJSONObject("settings")),cfg=settings();JSONArray records=in.getJSONArray("entries"),validated=new JSONArray();if(records.length()>20000)throw new Exception("Yedek kayıt sınırını aşıyor.");Set<String> ids=new HashSet<>();for(int i=0;i<records.length();i++){JSONObject x=records.getJSONObject(i),r=validate(x);if(!ids.add(r.getString("id")))throw new Exception("Yedekte tekrarlı kapanış var.");r.put("revision",Math.max(1,x.optInt("revision",1))).put("savedAt",x.optLong("savedAt",System.currentTimeMillis())).put("reason",x.optString("reason","Yedekten alındı"));validated.put(r);}for(String field:new String[]{"cashboxes","denoms"}){Set<String> existing=new HashSet<>();JSONArray a=cfg.getJSONArray(field),b=incoming.getJSONArray(field);for(int i=0;i<a.length();i++)existing.add(a.getJSONObject(i).getString("id"));for(int i=0;i<b.length();i++)if(existing.add(b.getJSONObject(i).getString("id")))a.put(b.getJSONObject(i));}cfg=config(cfg);Set<String> known=new HashSet<>();for(int i=0;i<cfg.getJSONArray("cashboxes").length();i++)known.add(cfg.getJSONArray("cashboxes").getJSONObject(i).getString("id"));for(int i=0;i<validated.length();i++)if(!known.contains(validated.getJSONObject(i).getString("cashId")))throw new Exception("Yedekte tanımsız kasa var.");JSONArray pos=in.optJSONArray("pos"),validPos=new JSONArray();if(pos!=null){if(pos.length()>20000)throw new Exception("POS yedek sınırı aşıldı.");for(int i=0;i<pos.length();i++){JSONObject r=validatePos(pos.getJSONObject(i));if(!known.contains(r.getString("cashId")))throw new Exception("POS kasası tanımsız.");validPos.put(r);}}SQLiteDatabase d=getWritableDatabase();int added=0,skipped=0;d.beginTransaction();try{ContentValues c=new ContentValues();c.put("data",cfg.toString());d.update("settings",c,"id=1",null);for(int i=0;i<validated.length();i++){JSONObject r=validated.getJSONObject(i);if(find(r.getString("id"))==null){putEntry(d,r);added++;}else skipped++;}for(int i=0;i<validPos.length();i++){JSONObject r=validPos.getJSONObject(i);PosLedger.ensureNoTotal(d,r);ContentValues v=new ContentValues();v.put("id",r.getString("id"));v.put("data",r.toString());d.insertWithOnConflict("pos",null,v,SQLiteDatabase.CONFLICT_IGNORE);}PosLedger.merge(d,in,known);d.setTransactionSuccessful();}finally{d.endTransaction();}return "POS kayıtları mevcutların üzerine yazılmadan eklendi. "+added+" kapanış eklendi; mevcut "+skipped+" kapanış korundu. Taslaklar ve eski revizyonlar yedekte saklanır; içe aktarmada yalnız güncel kapanışlar eklenir.";}
 synchronized JSONObject savePos(String raw)throws Exception{
  JSONObject in=new JSONObject(raw),r=validatePos(in);boolean active=false;JSONArray boxes=settings().getJSONArray("cashboxes");for(int i=0;i<boxes.length();i++)if(boxes.getJSONObject(i).getString("id").equals(r.getString("cashId"))&&boxes.getJSONObject(i).optBoolean("active"))active=true;if(!active)throw new Exception("Etkin Kasa Seçin.");SQLiteDatabase d=getWritableDatabase();d.beginTransaction();try{
   PosLedger.ensureNoTotal(d,r);String original=in.optString("originalId",r.getString("id"));JSONObject old=PosLedger.find(d,"pos",original),destination=PosLedger.find(d,"pos",r.getString("id"));
   if(in.has("originalId")&&old==null)throw new Exception("Düzenlenen POS Kaydı Artık Yok. Güncel Listeyi Açın.");
   if(old!=null&&!old.getString("cashId").equals(r.getString("cashId")))throw new Exception("Tarih Düzeltmesinde Kasa Değiştirilemez.");
   if(!original.equals(r.getString("id"))&&destination!=null)throw new Exception("Yeni Tarihte Bu Kasa / POS İçin Kayıt Var. Üzerine Yazılmadı.");
   String reason=in.optString("reason","").trim();if(old!=null&&(reason.length()<3||in.optInt("baseRevision")!=old.optInt("revision",1)))throw new Exception("Bu POS Kaydı Zaten Var. Güncel Kaydı Açıp Gerekçeli Düzeltin.");
   if(old==null&&in.optInt("baseRevision")>0)throw new Exception("Düzenleme Kaydı Bulunamadı.");
   if(old!=null&&in.has("originalSavedAt")&&in.getLong("originalSavedAt")!=old.getLong("savedAt"))throw new Exception("POS Kaydı Değişti. Güncel Kaydı Açın.");
   r.put("revision",old==null?1:old.optInt("revision",1)+1).put("reason",reason);if(old!=null){ContentValues a=new ContentValues();a.put("data",old.toString());d.insertOrThrow("pos_revisions",null,a);if(!original.equals(r.getString("id")))d.delete("pos","id=?",new String[]{original});}PosLedger.put(d,"pos",r);d.setTransactionSuccessful();return r;
  }finally{d.endTransaction();}
 }
 static JSONObject validatePos(JSONObject in)throws Exception{String cash=text(in,"cashId",80),terminal=text(in,"terminal",60),date=day(in);if(!cash.matches("[a-zA-Z0-9_-]+"))throw new Exception("Kasa geçersiz.");JSONArray a=in.getJSONArray("lines"),clean=new JSONArray();Set<String> seen=new HashSet<>();long total=0;for(int i=0;i<a.length();i++){JSONObject l=a.getJSONObject(i);String type=l.getString("type");if(!Arrays.asList("creditDomestic","creditOwn","world","creditForeign","debitForeign","debitDomestic","debitOwn").contains(type)||!seen.add(type))throw new Exception("POS kategorisi geçersiz veya tekrarlı.");long amount=number(l,"amount");if(amount<1)throw new Exception("POS tutarı pozitif olmalı.");int delay=type.equals("debitDomestic")||type.equals("debitOwn")?15:21;String due=LocalDate.parse(date).plusDays(delay).toString();total=CashMath.add(total,amount);clean.put(new JSONObject().put("type",type).put("label",text(l,"label",80)).put("amount",amount).put("delay",delay).put("due",due));}if(clean.length()==0)throw new Exception("POS satırı gerekli.");return new JSONObject().put("id",cash+"_"+date+"_"+terminal.toLowerCase(java.util.Locale.ROOT)).put("cashId",cash).put("cashName",text(in,"cashName",60)).put("date",date).put("terminal",terminal).put("lines",clean).put("total",total).put("savedAt",System.currentTimeMillis());}
 synchronized int deleteCounts(String raw)throws Exception{JSONObject in=new JSONObject(raw);if(!in.optBoolean("confirmed",false))throw new Exception("Silme Onayı Gerekli.");JSONArray targets=in.getJSONArray("targets");if(targets.length()<1||targets.length()>100)throw new Exception("Bir İşlemde 1–100 Sayım Silinebilir.");SQLiteDatabase d=getWritableDatabase();d.beginTransaction();try{Set<String> ids=new HashSet<>();for(int i=0;i<targets.length();i++){JSONObject t=targets.getJSONObject(i);String id=text(t,"id",100);if(!ids.add(id))throw new Exception("Tekrarlı Silme Hedefi.");JSONObject old=find(id);if(old==null||t.getInt("revision")!=old.getInt("revision")||t.getLong("savedAt")!=old.getLong("savedAt"))throw new Exception("Kayıt Değişti Veya Silindi. Geçmişi Yenileyip Tekrar Onaylayın.");}for(String id:ids){d.delete("drafts","id=?",new String[]{id});d.delete("revisions","entry_id=?",new String[]{id});if(d.delete("entries","id=?",new String[]{id})!=1)throw new Exception("Silme Tamamlanamadı.");}d.setTransactionSuccessful();return ids.size();}finally{d.endTransaction();}}
 synchronized JSONObject savePosTotal(String raw)throws Exception{return PosLedger.saveTotal(this,raw);}
 synchronized JSONObject receivePos(String raw)throws Exception{return PosLedger.receive(this,raw);}
}
